	@Test
	void targetShapeCopiesValuesAAndNotValuesG() {
		TupleExpr plan = optimize(TARGET_QUERY, GraphScopeOptimizer.Options.DEFAULT);

		Graph graph = graphs(plan).get(0);
		assertThat(graph.getArg()).isInstanceOf(Join.class);
		Join join = (Join) graph.getArg();
		assertThat(join.getLeftArg()).isInstanceOf(BindingSetAssignment.class);
		BindingSetAssignment copy = (BindingSetAssignment) join.getLeftArg();
		assertThat(copy.getDeclaredBindingNames()).containsExactly("a");
		assertThat(copy.hasRepeatableBindingSets()).isTrue();
		assertThat(copy.getBindingSets()).hasSize(3);
		assertThat(assignmentsIn(graph.getArg())).hasSize(1);
		// The original body is retained unchanged on the right.
		assertThat(join.getRightArg()).isNotInstanceOf(BindingSetAssignment.class);
		// Both outer tables remain where they were.
		List<BindingSetAssignment> outer = assignmentsOutsideGraphs(plan);
		assertThat(outer).hasSize(2);
		assertThat(outer.stream().map(a -> a.getDeclaredBindingNames().iterator().next()).toList())
				.containsExactly("a", "g");
		assertThat(rowCount(outer.get(0))).isEqualTo(3);
		assertThat(rowCount(outer.get(1))).isEqualTo(5);
	}

