	@Test
	void valuesOutsideTheJoinGroupAreNotUsed() {
		String graph = "GRAPH ?g { ?a a ?t }";
		String values = "VALUES ?a { <http://example.com/test1> <http://example.com/test2> }";
		// VALUES in an OPTIONAL sibling, a UNION branch, or when the graph is itself in an OPTIONAL/UNION branch.
		assertNotCopied("SELECT * { " + graph + " OPTIONAL { " + values + " } }");
		assertNotCopied("SELECT * { { " + values + " } UNION { ?x a ?y } " + graph + " }");
		assertNotCopied("SELECT * { " + values + " OPTIONAL { " + graph + " } }");
		assertNotCopied("SELECT * { " + values + " { " + graph + " } UNION { ?x a ?y } }");
		assertNotCopied("SELECT * { " + values + " MINUS { " + graph + " } }");
		assertNotCopied("SELECT * { " + values + " FILTER EXISTS { " + graph + " } }");
	}

