	@Test
	void nestedVariableGraphsReachTheirFixedPointInASingleRun() {
		// A nested GRAPH is a binding-injection barrier, so the outer body is rejected and nothing is copied.
		TupleExpr rejected = optimize("SELECT * { VALUES ?a { <http://example.com/test1> <http://example.com/test2> } "
				+ "GRAPH ?g { ?x a ?y . GRAPH ?h { ?a a ?t } } }", GraphScopeOptimizer.Options.DEFAULT);
		assertThat(assignmentsInGraphs(rejected)).as(rejected.toString()).isEmpty();
		assertIdempotent(rejected);

		// A table inside the outer body is a sibling of the inner graph and is copied into it in the same run.
		TupleExpr inner = optimize("SELECT * { VALUES ?a { <http://example.com/test1> <http://example.com/test2> } "
				+ "GRAPH ?g { VALUES ?a { <http://example.com/test1> <http://example.com/test2> } "
				+ "GRAPH ?h { ?a a ?t } } }", GraphScopeOptimizer.Options.DEFAULT);
		List<Graph> graphs = graphs(inner);
		assertThat(graphs).hasSize(2);
		assertThat(assignmentsIn(graphs.get(1).getArg())).as(inner.toString()).hasSize(1);
		assertIdempotent(inner);
	}

	private static void assertIdempotent(TupleExpr plan) {
		TupleExpr afterFirst = plan.clone();
		new GraphScopeOptimizer().optimize(plan, null, EmptyBindingSet.getInstance());
		assertThat(plan).isEqualTo(afterFirst);
	}

	@Test
	void anEquivalentTableWrittenAtTheTopOfTheGraphBodyIsNotCopiedAgain() {
		TupleExpr plan = optimize("SELECT * { VALUES ?a { <http://example.com/test1> <http://example.com/test2> } "
				+ "GRAPH ?g { VALUES ?a { <http://example.com/test2> <http://example.com/test1> "
				+ "<http://example.com/test1> } ?a a ?t } }", GraphScopeOptimizer.Options.DEFAULT);

		// The user's table is the only one inside the graph; it has the same distinct rows as the sibling.
		assertThat(assignmentsInGraphs(plan)).as(plan.toString()).hasSize(1);
		TupleExpr afterFirst = plan.clone();
		new GraphScopeOptimizer().optimize(plan, null, EmptyBindingSet.getInstance());
		assertThat(plan).isEqualTo(afterFirst);
	}

