	@Test
	void bodyThatRequiresIndependentEvaluationIsNotCopied() {
		// A nested group is a scope change; Join(copy, body) would hash-join and constrain nothing.
		String query = "SELECT * { VALUES ?a { <http://example.com/test1> <http://example.com/test2> } "
				+ "GRAPH ?g { { ?a a ?t } } }";
		assertNotCopied(query);
		assertParity(query, false);

		String union = "SELECT * { VALUES ?a { <http://example.com/test1> <http://example.com/test2> } "
				+ "GRAPH ?g { { ?a a ?t } UNION { ?a <http://example.com/p1> ?t } } }";
		assertNotCopied(union);
		assertParity(union, false);
	}

