	@Test
	void iterationStopsRightAfterTheDistinctRowBudgetIsExceeded() {
		List<BindingSet> rows = new ArrayList<>();
		for (int i = 0; i < 1000; i++) {
			rows.add(row("a", iri("test" + i)));
		}
		CountingRows counting = new CountingRows(rows);
		BindingSetAssignment table = new BindingSetAssignment();
		table.setDeclaredBindingNames(Set.of("a"));
		table.setBindingSets(counting);

		assertThat(optimizeTable(table).isEmpty()).isTrue();
		assertThat(counting.rowsReturned).hasValueLessThanOrEqualTo(GraphScopeOptimizer.MAX_COPIED_ROWS + 1);
		assertThat(counting.rowsReturned).hasValueGreaterThan(0);
	}

